            {
              "type": "null"
            }
          ],
          "default": null,
          "description": "When, relative to the existing steps, if the rule says so; or null",
          "title": "Timing"
        },
        "already_in_description": {
          "default": false,
          "description": "true if the description already contains this step",
          "title": "Already In Description",
          "type": "boolean"
        }
      },
      "required": [
        "label"
      ],
      "title": "Step",
      "type": "object"
    }
  },
  "properties": {
    "label": {
      "enum": [
        "applicable",
        "not_applicable",
        "indeterminate",
        "irrelevant"
      ],
      "title": "Label",
      "type": "string"
    },
    "facts": {
      "items": {
        "$ref": "#/$defs/Fact"
      },
      "title": "Facts",
      "type": "array"
    },
    "reason": {
      "description": "One or two sentences",
      "title": "Reason",
      "type": "string"
    },
    "required_steps": {
      "description": "Only for applicable",
      "items": {
        "$ref": "#/$defs/Step"
